import {DatabaseSync} from 'node:sqlite';import {readFile} from 'node:fs/promises';import path from 'node:path';
let input='';for await(const chunk of process.stdin)input+=chunk;const {url,token,mode,root}=JSON.parse(input);
const rpc=async(action,payload={})=>{const r=await fetch(url+'/api',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({action,payload})});if(!r.ok)throw Error('synthetic request failed');return r.json();};
if(mode==='save')await rpc('intake.loadNativePractice',{});
const status=await rpc('intake.status');if(status.sources.length!==2||!status.nativePractice?.preannotated)throw Error('lost practice');const ids=status.sources.map(s=>s.id);const original=await rpc('intake.readDocument',{id:ids[0]});if(!original.original.includes('ENSAYO-NATIVO-4702'))throw Error('lost original');const compared=await rpc('intake.compareVersions',{ids});if(!JSON.stringify(compared.result).includes('30'))throw Error('lost comparison');
const file=path.join(root,'native-pilot-v1/rust-case/rejon-protegido.sqlite');const bytes=await readFile(file);if(bytes.includes(Buffer.from('ENSAYO-NATIVO-4702')))throw Error('plaintext');const db=new DatabaseSync(file,{readOnly:true});if(db.prepare('PRAGMA integrity_check').get().integrity_check!=='ok')throw Error('integrity');db.close();
